UPDATE place_content pc
  JOIN place sp ON sp.place_id = pc.place_id
   SET pc.description = #{description}
 WHERE sp.place_group_id = (SELECT place_group_id FROM (SELECT place_group_id FROM place WHERE place_id = #{placeId}) t)
   AND pc.language      = #{language}
   AND pc.difficulty    = #{difficulty}
